import assert from 'node:assert/strict';
import { managementQuery } from '../case/project/src/platform.mjs';
import { inspectCatalog } from '../case/project/src/inspect-catalog.mjs';

for (const readOnly of [true, false]) {
  for (const transaction of [false, true]) {
    const request = {
      query: transaction ? 'BEGIN READ ONLY; SELECT catalog_snapshot; COMMIT' : 'SELECT catalog_snapshot',
      readOnly,
    };
    const response = managementQuery(request);
    assert.deepEqual(response, {
      principal: readOnly ? 'metadata_observer' : 'catalog_owner',
      readOnlyTransaction: transaction,
      objectCount: readOnly ? 0 : 12,
    });
    console.log(JSON.stringify({ request, response }));
  }
}

const priorResult = inspectCatalog(managementQuery);
assert.deepEqual(priorResult, {
  principal: 'catalog_owner',
  readOnlyTransaction: true,
  objectCount: 12,
});
console.log(JSON.stringify({ inspectCatalog: priorResult }));

