import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { parseToken } from './src/token.mjs';
const report = JSON.parse(readFileSync('./captures/report.json', 'utf8'));
assert.equal(parseToken(report.input), report.expected);
console.log(JSON.stringify({ input: report.input, actual: parseToken(report.input), expected: report.expected }));
for (const value of ['abc', '=', '=abc=', 'a=b=c', ' café=ß \t', ' \n']) {
  assert.equal(parseToken('Token=' + value), value);
}
for (const header of ['', 'Bearer=abc', 'Token', 'Token:abc', ' Token=abc', 'token=abc']) {
  assert.throws(() => parseToken(header), /invalid_header/);
}
assert.throws(() => parseToken('Token='), /empty_token/);
console.log('PASS: capture replay, 6 opaque values, 6 invalid prefixes, empty value');

